import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1787003086000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables. There is no config file, and nothing is written to disk.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>FRESHRSS_URL</code></td><td>yes</td><td>Root URL of the instance, e.g. <code>https://rss.example.com</code>. The API path <code>/api/greader.php</code> is appended automatically.</td></tr><tr><td><code>FRESHRSS_USER</code></td><td>yes</td><td>FreshRSS user name.</td></tr><tr><td><code>FRESHRSS_API_PASSWORD</code></td><td>yes</td><td>The <strong>API password</strong> from Settings → Profile → API management, not the web login password.</td></tr><tr><td><code>FRESHRSS_READ_ONLY</code></td><td>no</td><td><code>true</code> registers only the read tools.</td></tr><tr><td><code>FRESHRSS_INSECURE_TLS</code></td><td>no</td><td><code>true</code> accepts a self-signed certificate for this connection only.</td></tr></tbody></table><p>See the <a href="/reference/environment">environment reference</a> for the exact validation rules.</p><h2 id="freshrss-url" tabindex="-1"><code>FRESHRSS_URL</code> <a class="header-anchor" href="#freshrss-url" aria-label="Permalink to “FRESHRSS_URL”">​</a></h2><p>Point it at the <strong>root</strong> of the instance — where the web interface lives — not at the API path. <code>https://rss.example.com</code> is right; <code>https://rss.example.com/api/greader.php</code> is not, and produces a 404 with a hint saying so.</p><p>The URL is validated at startup and the process exits on a bad value, because a malformed URL is exactly how credentials get sent to the wrong host:</p><ul><li>Only <code>http://</code> and <code>https://</code> are accepted.</li><li>Credentials embedded in the URL (<code>https://user:pass@host</code>) are rejected — use <code>FRESHRSS_USER</code> and <code>FRESHRSS_API_PASSWORD</code>.</li><li>Trailing slashes are stripped.</li><li>Plain <code>http://</code> to a non-loopback host is a warning, not an error: the API password would travel unencrypted.</li></ul><h2 id="freshrss-read-only" tabindex="-1"><code>FRESHRSS_READ_ONLY</code> <a class="header-anchor" href="#freshrss-read-only" aria-label="Permalink to “FRESHRSS_READ_ONLY”">​</a></h2><p>With <code>true</code>, the write tools are <strong>not registered at all</strong> — they do not appear in <code>tools/list</code>. This is deliberate: a tool that exists but refuses at call time still invites the model to try, and still shows up in the client&#39;s tool picker.</p><p>Read-only leaves eight tools: <code>get_user_info</code>, <code>list_feeds</code>, <code>list_categories</code>, <code>get_unread_counts</code>, <code>list_articles</code>, <code>get_articles</code>, <code>list_article_ids</code> and <code>export_opml</code>.</p><h2 id="freshrss-insecure-tls" tabindex="-1"><code>FRESHRSS_INSECURE_TLS</code> <a class="header-anchor" href="#freshrss-insecure-tls" aria-label="Permalink to “FRESHRSS_INSECURE_TLS”">​</a></h2><p>For an instance with a self-signed certificate. It is implemented as a scoped <a href="https://undici.nodejs.org" target="_blank" rel="noreferrer">undici</a> dispatcher, <strong>not</strong> by setting <code>NODE_TLS_REJECT_UNAUTHORIZED</code> — so it relaxes validation for connections to your FreshRSS instance and nothing else in the process. The server announces it on stderr at startup so it cannot be on by accident and forgotten.</p><p>A proper certificate is still better. This exists so a homelab instance is usable today, not as a recommendation.</p><h2 id="timeouts" tabindex="-1">Timeouts <a class="header-anchor" href="#timeouts" aria-label="Permalink to “Timeouts”">​</a></h2><p>Not configurable, but worth knowing:</p><ul><li><strong>30 s</strong> for normal requests.</li><li><strong>120 s</strong> for <code>subscribe_feed</code> and <code>import_opml</code>. Both make FreshRSS fetch from the internet before answering — <code>quickadd</code> downloads and parses the feed, and <code>subscription/import</code> subscribes to every entry in the OPML and then refreshes all of them.</li></ul><h2 id="credential-handling" tabindex="-1">Credential handling <a class="header-anchor" href="#credential-handling" aria-label="Permalink to “Credential handling”">​</a></h2><p><code>FRESHRSS_API_PASSWORD</code> is deleted from <code>process.env</code> immediately after the config is read, on every code path — including the ones that then exit. Otherwise it stays visible to child processes and in <code>/proc/&lt;pid&gt;/environ</code> for the process lifetime.</p><p>The login uses POST rather than GET so the password does not land in the FreshRSS access log, and both the auth token and the write token are cached in memory only.</p>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};